if (root == nullptr || encLen == 0) return;

std::stack<TreeNode*> nodeStack;
nodeStack.push(root);
int bitIndex = 0;
decLen = 0;

while (!nodeStack.empty() && bitIndex < encLen) {
    TreeNode* current = nodeStack.top();
    nodeStack.pop();

    if (current->isLeaf) {
        decoded[decLen++] = current->value;
        bitIndex = 0; // Reset bit index for next symbol
        nodeStack.push(root); // Start from root for next symbol
        continue;
    }

    // Push right child first (so left is processed first due to stack LIFO)
    if (current->right != nullptr) {
        nodeStack.push(current->right);
    }
    if (current->left != nullptr) {
        nodeStack.push(current->left);
    }

    // Move to next bit in encoded array
    bitIndex++;
}

// END_CODE

